function renderCanvasCardPalette(){const palette=$('#canvasCardPalette');if(!palette)return;palette.innerHTML=SHAPES.map(shape=>`<button type="button" class="canvas-card-palette-button ${state.canvasCardTool===shape.id?'active':''}" data-canvas-card-shape="${shape.id}" role="menuitem" aria-label="${escapeHtml(i18nSource(shape.name))}">${canvasShapeIcon(shape.id)}</button>`).join('');$$('[data-canvas-card-shape]',palette).forEach(button=>button.onclick=e=>{e.preventDefault();e.stopPropagation();armCanvasCardTool(button.dataset.canvasCardShape)})}
