function toggleCanvasCardPalette(){if(!state.currentCanvas){toast('Create a canvas first');return}const palette=$('#canvasCardPalette'),button=$('#addNodePanelBtn');if(!palette||!button)return;const opening=palette.classList.contains('hidden');if(!opening)return closeCanvasCardPalette();cancelCanvasFigureTool();closeCanvasViewPopover();$('#canvasAddCardTooltip')?.classList.add('hidden');renderCanvasCardPalette();palette.classList.remove('hidden');button.setAttribute('aria-expanded','true');positionCanvasCardPalette()}
