function toggleCanvasFigurePalette(){if(!state.currentCanvas){toast('Create a canvas first');return}const palette=$('#canvasFigurePalette'),button=$('#addFigureBtn');if(!palette||!button)return;const opening=palette.classList.contains('hidden');if(!opening)return closeCanvasFigurePalette();cancelCanvasCardTool();closeCanvasViewPopover();$('#canvasAddFigureTooltip')?.classList.add('hidden');renderCanvasFigurePalette();palette.classList.remove('hidden');button.setAttribute('aria-expanded','true');positionCanvasFigurePalette()}
