  const paint=point=>{last=point;const dx=point.x-start.x,dy=point.y-start.y,distance=Math.hypot(dx,dy);if(!moved&&distance<4)return;if(!moved){moved=true;preview.classList.remove('hidden')}const left=Math.min(start.x,point.x),top=Math.min(start.y,point.y),w=Math.max(1,Math.abs(dx)),h=Math.max(1,Math.abs(dy));Object.assign(preview.style,{left:`${left}px`,top:`${top}px`,width:`${w}px`,height:`${h}px`})};
