  const up=async e=>{cleanup();paint(canvasPointFromClient(e.clientX,e.clientY));const left=moved?Math.min(start.x,last.x):start.x,top=moved?Math.min(start.y,last.y):start.y,w=moved?Math.max(80,Math.abs(last.x-start.x)):defaults.w,h=moved?Math.max(50,Math.abs(last.y-start.y)):defaults.h;preview.remove();cancelCanvasCardTool();setCanvasMode('pointer');try{await createNodeAt(shape,Math.max(0,left),Math.max(0,top),{w,h},{inspect:false})}catch(error){toast(error.message||'Card could not be created.')}};
  const cancel=()=>{cleanup();preview.remove()};
