function figureDrawDefaults(shape){if(shape==='circle')return{w:180,h:180};if(shape==='triangle')return{w:200,h:170};if(shape==='oval')return{w:240,h:150};if(shape==='line')return{w:260,h:30};return{w:260,h:160}}
