function snapLineFigureEndpoint(origin,point){const dx=point.x-origin.x,dy=point.y-origin.y,distance=Math.hypot(dx,dy);if(distance<0.0001)return{x:point.x,y:point.y};const step=Math.PI/4,angle=Math.round(Math.atan2(dy,dx)/step)*step;return{x:origin.x+Math.cos(angle)*distance,y:origin.y+Math.sin(angle)*distance}}
